using System;
using System.Collections;
using System.Collections.Generic;
using System.Text.Json.Serialization;

namespace bankingonaspdotnet.Domain;

/// <summary>
/// RateType enumerator class
/// </summary>
[JsonConverter(typeof(JsonStringEnumConverter))]

public enum RateType
{
    Fixed = 1, Variable = 2
}

/// <summary>
/// Extension of capabilities for the RateType enum
/// </summary>
public static class RateTypeExtensions
{
    //************************************************************************
    // static implementations
    //************************************************************************
    public static List<RateType> GetValues()
    {
        return Enum.GetValues<RateType>().ToList();
    }

    public static RateType GetDefaultValue()
    {
        return Enum.GetValues<RateType>().First();
    }

    public static RateType WhichOne(string name)
    {
        if (Enum.TryParse<RateType>(name, true, out var value))
        {
            return value;
        }

        return GetDefaultValue();
    }
}



